const discoveryPriority:Record<string,number> = { postalClue:1, bankHistoryClue:2, estateNoticeClue:3, estateRegistry:4, familyRegistry:5, willStorage:6, financialInquiry:7, municipalityWindow:8, notaryOffice:9, familyCourt:10, deadlineGuide:11, taxOffice:12, documentsReuse:13 };
function discoveryRank(discovery:DiscoveryDefinition){return discovery.priority??discoveryPriority[discovery.id]??99}
function discoveryStatus(state:JourneyState,id:DiscoveryId){if(state.currentDiscoveryId===id&&state.pendingDiscoveryIds?.includes(id))return 'new';if(state.pendingDiscoveryIds?.includes(id))return 'pending';if(state.savedDiscoveryIds?.includes(id)||state.programs[id]==='saved'||state.programs[id]==='done')return 'saved';if(state.seenDiscoveryIds?.includes(id))return 'seen';return 'pending'}
function newlyUnlockedDiscoveryIds(state:JourneyState,known:DiscoveryId[]=[]){const existing=new Set([...(known||[]),...(state.discoveredIds||[]),...(state.seenDiscoveryIds||[]),...(state.pendingDiscoveryIds||[])]);return discoveryDefinitions.filter(def=>def.conditions(state)&&!existing.has(def.id)).sort((a,b)=>discoveryRank(a)-discoveryRank(b)).map(def=>def.id)}
function queueDiscoveries(state:JourneyState,ids:DiscoveryId[]){const fresh=ids.filter(id=>discoveryDefinitions.some(def=>def.id===id)&&!(state.discoveredIds||[]).includes(id)&&!(state.seenDiscoveryIds||[]).includes(id)&&!(state.pendingDiscoveryIds||[]).includes(id));if(!fresh.length)return state;const discovered=Array.from(new Set([...(state.discoveredIds||[]),...fresh]));const pending=Array.from(new Set([...(state.pendingDiscoveryIds||[]),...fresh]));const order=Array.from(new Set([...(state.discoveryOrder||[]),...fresh]));return {...state,discoveredIds:discovered,pendingDiscoveryIds:pending,newDiscoveryIds:pending,discoveryOrder:order,currentDiscoveryId:state.currentDiscoveryId&&pending.includes(state.currentDiscoveryId)?state.currentDiscoveryId:pending[0]??fresh[0]}}
function orderedDiscoveries(state:JourneyState){const ids=Array.from(new Set([...(state.discoveryOrder||[]),...(state.discoveredIds||[])]));const current=state.currentDiscoveryId&&ids.includes(state.currentDiscoveryId)?[state.currentDiscoveryId]:[];const rest=ids.filter(id=>!current.includes(id));return [...current,...rest].map(id=>discoveryDefinitions.find(def=>def.id===id)).filter((def):def is DiscoveryDefinition=>Boolean(def&&(def.conditions(state)||(state.discoveredIds||[]).includes(def.id))))}

